I’m implementing a streaming decoder in Python. Each record is a positive decimal count, a colon, and exactly one ASCII letter; records are separated by semicolons, with no trailing separator. Leading zeros are allowed if the count is positive, and an empty stream decodes to an empty string. Chunks may split anywhere. The decoder must eventually enforce a caller-supplied maximum total decoded length before allocating expanded text, using only the standard library.

```python
class Decoder:
    def __init__(self):
        self.pending = ''
        self.output = ''

    def feed(self, chunk):
        self.pending += chunk
        parts = self.pending.split(';')
        for part in parts:
            if ':' in part:
                n, letter = part.split(':')
                self.output += letter * int(n)
        self.pending = parts[-1]
        return self.output

    def finish(self):
        return self.output
```

First, make the grammar and the implications of arbitrary chunk boundaries precise. What must the decoder retain between feeds before it can decide whether a record is valid?

```python
class Decoder:
    """feed() and finish() return only text committed by that call."""

    def __init__(self, max_length):
        if (not isinstance(max_length, int) or isinstance(max_length, bool)
                or max_length < 0):
            raise ValueError('max_length must be a nonnegative integer')
        self.max_length = max_length
        self.total = 0
        self.state = 'start'
        self.count = 0
        self.letter = None

    def _fail(self, message):
        self.state = 'error'
        raise ValueError(message)

    def _check_open(self):
        if self.state in ('error', 'finished'):
            raise RuntimeError(f'decoder is {self.state}')

    def _commit(self):
        # The count was checked against the remaining allowance while parsing.
        text = self.letter * self.count
        self.total += self.count
        self.count = 0
        self.letter = None
        return text

    def feed(self, chunk):
        self._check_open()
        if not isinstance(chunk, str):
            self._fail('chunk must be a string')
        output = []
        for char in chunk:
            if self.state in ('start', 'after_separator', 'count'):
                if '0' <= char <= '9':
                    digit = ord(char) - ord('0')
                    remaining = self.max_length - self.total
                    if self.count > (remaining - digit) // 10:
                        self._fail('decoded length limit exceeded')
                    self.count = self.count * 10 + digit
                    self.state = 'count'
                elif char == ':' and self.state == 'count':
                    if self.count == 0:
                        self._fail('count must be positive')
                    self.state = 'letter'
                else:
                    self._fail('expected a count or colon')
            elif self.state == 'letter':
                if not ('A' <= char <= 'Z' or 'a' <= char <= 'z'):
                    self._fail('expected one ASCII letter')
                self.letter = char
                self.state = 'end_record'
            else:  # end_record
                if char != ';':
                    self._fail('expected a separator or end of stream')
                output.append(self._commit())
                self.state = 'after_separator'
        return ''.join(output)

    def finish(self):
        self._check_open()
        if self.state == 'start':
            result = ''
        elif self.state == 'end_record':
            result = self._commit()
        else:
            self._fail('incomplete record or trailing separator')
        self.state = 'finished'
        return result
```

A malformed chunk or limit failure puts the decoder in `error`; subsequent calls raise `RuntimeError`. If a call fails after committing earlier records within that same call, it raises instead of returning that call's output. Output returned by earlier calls remains valid but cannot be retracted.

The reference parses the complete string using the grammar directly; the test tries every partition of each short stream. It compares successful output and treats a `ValueError` from either `feed()` or `finish()` as rejection. Replace `decoder` with the module containing the existing class.

```python
import re
import unittest

from decoder import Decoder


RECORD = re.compile(r'([0-9]+):([A-Za-z])', re.ASCII)


def reference_decode(stream, limit):
    if stream == '':
        return ''
    parts = []
    total = 0
    for record in stream.split(';'):
        match = RECORD.fullmatch(record)
        if match is None:
            raise ValueError('invalid record')
        count = int(match.group(1))
        if count == 0 or count > limit - total:
            raise ValueError('invalid count or limit exceeded')
        total += count
        parts.append((count, match.group(2)))
    return ''.join(letter * count for count, letter in parts)


def partitions(stream):
    if not stream:
        yield []
        return
    # Each bit chooses whether to split at a character boundary.
    for mask in range(1 << (len(stream) - 1)):
        chunks = []
        start = 0
        for i in range(1, len(stream)):
            if mask & (1 << (i - 1)):
                chunks.append(stream[start:i])
                start = i
        chunks.append(stream[start:])
        yield chunks


class DecoderComparisonTests(unittest.TestCase):
    def test_partitions(self):
        cases = [
            ('', 0), ('1:A', 1), ('02:a;1:B', 3),
            ('0:A', 10), ('2:', 10), ('1:A;;1:B', 10),
            ('1:é', 10), ('1:A;', 10), ('1:AB', 10),
            ('3:A', 2), ('1:A;2:B', 2),
        ]
        for stream, limit in cases:
            try:
                expected = reference_decode(stream, limit)
                valid = True
            except ValueError:
                valid = False

            for chunks in partitions(stream):
                with self.subTest(stream=stream, limit=limit, chunks=chunks):
                    decoder = Decoder(limit)
                    output = []
                    try:
                        for chunk in chunks:
                            output.append(decoder.feed(chunk))
                        output.append(decoder.finish())
                    except ValueError:
                        self.assertFalse(valid)
                        with self.assertRaises(RuntimeError):
                            decoder.finish()
                    else:
                        self.assertTrue(valid)
                        self.assertEqual(''.join(output), expected)


if __name__ == '__main__':
    unittest.main()
```

The reference uses `int()` and is intended for these small test inputs, not adversarial counts with arbitrarily many digits. Rejected streams can yield partial output before failure, so the test compares full output only for valid streams.
